    public static final class Icon extends View {private final Paint p=new Paint(3);private String kind;public int color=MUTED;public Icon(Context c,String type){super(c);kind=type;}public void setKind(String type){kind=type;invalidate();}@Override protected void onDraw(Canvas c){super.onDraw(c);c.save();float size=Math.min(getWidth(),getHeight())*.62f;c.translate((getWidth()-size)/2,(getHeight()-size)/2);c.scale(size/24,size/24);p.setColor(color);p.setStrokeWidth(2.0f);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);Path x=new Path();switch(kind){case "download":c.drawLine(12,3,12,16,p);c.drawLine(7,11,12,16,p);c.drawLine(17,11,12,16,p);x.moveTo(4,17);x.lineTo(4,21);x.lineTo(20,21);x.lineTo(20,17);c.drawPath(x,p);break;case "calendar":c.drawRoundRect(4,5,20,21,2,2,p);c.drawLine(4,10,20,10,p);c.drawLine(8,3,8,7,p);c.drawLine(16,3,16,7,p);c.drawLine(8,14,8,14,p);c.drawLine(12,14,12,14,p);c.drawLine(16,14,16,14,p);c.drawLine(8,18,8,18,p);c.drawLine(12,18,12,18,p);c.drawLine(16,18,16,18,p);break;case "search":c.drawCircle(10,10,6.3f,p);c.drawLine(15,15,21,21,p);break;case "back":x.moveTo(14,5);x.lineTo(7,12);x.lineTo(14,19);c.drawPath(x,p);break;case "close":c.drawLine(6,6,18,18,p);c.drawLine(18,6,6,18,p);break;case "play":x.moveTo(8,4);x.lineTo(20,12);x.lineTo(8,20);x.close();c.drawPath(x,p);break;case "heart":x.moveTo(12,20);x.cubicTo(-3,10,4,0,12,6);x.cubicTo(20,0,27,10,12,20);c.drawPath(x,p);break;case "home":x.moveTo(3,11);x.lineTo(12,3);x.lineTo(21,11);x.moveTo(6,10);x.lineTo(6,21);x.lineTo(18,21);x.lineTo(18,10);c.drawPath(x,p);break;case "grid":for(int i=0;i<2;i++)for(int j=0;j<2;j++)c.drawRoundRect(3+i*11,3+j*11,10+i*11,10+j*11,1.5f,1.5f,p);break;case "sources":x.moveTo(12,3);x.lineTo(22,8);x.lineTo(12,13);x.lineTo(2,8);x.close();x.moveTo(2,13);x.lineTo(12,18);x.lineTo(22,13);x.moveTo(2,18);x.lineTo(12,23);x.lineTo(22,18);c.drawPath(x,p);break;case "history":c.drawArc(4,4,21,21,-150,300,false,p);c.drawLine(3,4,3,10,p);c.drawLine(3,10,9,10,p);c.drawLine(12,8,12,13,p);c.drawLine(12,13,16,15,p);break;case "settings":c.drawCircle(12,12,7,p);c.drawCircle(12,12,2.5f,p);for(int i=0;i<8;i++){c.save();c.rotate(i*45,12,12);c.drawLine(12,1,12,4,p);c.restore();}break;case "filter":c.drawLine(3,5,21,5,p);c.drawLine(6,12,18,12,p);c.drawLine(9,19,15,19,p);break;case "expand":c.drawLine(3,9,3,3,p);c.drawLine(3,3,9,3,p);c.drawLine(15,3,21,3,p);c.drawLine(21,3,21,9,p);c.drawLine(21,15,21,21,p);c.drawLine(21,21,15,21,p);c.drawLine(9,21,3,21,p);c.drawLine(3,21,3,15,p);break;case "shrink":c.drawLine(9,3,9,9,p);c.drawLine(9,9,3,9,p);c.drawLine(15,3,15,9,p);c.drawLine(15,9,21,9,p);c.drawLine(15,21,15,15,p);c.drawLine(15,15,21,15,p);c.drawLine(9,21,9,15,p);c.drawLine(9,15,3,15,p);break;case "pause":c.drawLine(9,5,9,19,p);c.drawLine(15,5,15,19,p);break;case "pip":c.drawRoundRect(3,5,21,19,2,2,p);c.drawRoundRect(12,12,19,17,1.5f,1.5f,p);break;case "rewind":x.moveTo(11,6);x.lineTo(4,12);x.lineTo(11,18);x.close();c.drawPath(x,p);x.reset();x.moveTo(20,6);x.lineTo(13,12);x.lineTo(20,18);x.close();c.drawPath(x,p);break;case "forward":x.moveTo(4,6);x.lineTo(11,12);x.lineTo(4,18);x.close();c.drawPath(x,p);x.reset();x.moveTo(13,6);x.lineTo(20,12);x.lineTo(13,18);x.close();c.drawPath(x,p);break;case "prevEpisode":c.drawLine(6,5,6,19,p);x.moveTo(18,5);x.lineTo(8,12);x.lineTo(18,19);x.close();c.drawPath(x,p);break;case "nextEpisode":c.drawLine(18,5,18,19,p);x.moveTo(6,5);x.lineTo(16,12);x.lineTo(6,19);x.close();c.drawPath(x,p);break;case "fit":c.drawRoundRect(4,6,20,18,2,2,p);c.drawLine(8,10,8,14,p);c.drawLine(16,10,16,14,p);break;case "smartfill":c.drawRoundRect(3.5f,5,20.5f,19,3,3,p);x.moveTo(8,9);x.lineTo(5.5f,9);x.lineTo(5.5f,6.5f);x.moveTo(16,9);x.lineTo(18.5f,9);x.lineTo(18.5f,6.5f);x.moveTo(8,15);x.lineTo(5.5f,15);x.lineTo(5.5f,17.5f);x.moveTo(16,15);x.lineTo(18.5f,15);x.lineTo(18.5f,17.5f);c.drawPath(x,p);break;default:c.drawCircle(12,12,8,p);c.drawLine(12,8,12,13,p);c.drawPoint(12,17,p);}c.restore();}}
    public static void openOffline(Context c,String id,Anime a,double episode){c.startActivity(new Intent(c,PlayerActivity.class).putExtra("anime",a.json().toString()).putExtra("downloadId",id).putExtra("episode",episode));}
    public static String bytes(long n){if(n<0)return "—";if(n>=1024L*1024*1024)return String.format(new java.util.Locale("ru"),"%.2f ГБ",n/(1024.0*1024*1024));if(n>=1024L*1024)return String.format(new java.util.Locale("ru"),"%.1f МБ",n/(1024.0*1024));if(n>=1024)return String.format(new java.util.Locale("ru"),"%.0f КБ",n/1024.0);return n+" Б";}
    public static String videoSizeHint(int quality,int seconds){int q=quality<=0?720:quality;int duration=seconds>90?seconds:24*60;double mbPerMin=q<=360?3.2:q<=480?5.0:q<=720?8.5:q<=1080?15.0:q<=1440?25.0:38.0;long low=Math.max(20,Math.round(duration/60.0*mbPerMin*.75));long high=Math.max(low+10,Math.round(duration/60.0*mbPerMin*1.35));return "примерно "+bytes(low*1024L*1024L)+"–"+bytes(high*1024L*1024L);}
    public static String number(double n){return n==Math.floor(n)?String.valueOf((int)n):String.valueOf(n);}
